// Generated by ds.py mobile spec: measures every demo per theme at phone size (the fidelity anchor).
import { chromium } from '@playwright/test';
import { readdirSync, writeFileSync, mkdirSync } from 'node:fs';
const [base, outDir, themesJson, only] = process.argv.slice(2);
const themes = JSON.parse(themesJson);
const blocks = __BLOCKS__;   // file -> block class selector from each CSS header, e.g. button -> .btn
mkdirSync(`${outDir}/reference`, { recursive: true });
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 3, reducedMotion: 'reduce' });
await page.addInitScript(() => addEventListener('DOMContentLoaded', () => {
  const s = document.createElement('style');
  s.textContent = '*,*::before,*::after{transition:none!important;animation:none!important;caret-color:transparent!important}';
  document.head.appendChild(s);
}));
const files = readdirSync('components').filter((f) => f.endsWith('.html') && (!only || only.split(',').includes(f.slice(0, -5))));
const result = {};
for (const file of files) {
  const name = file.slice(0, -5);
  for (const theme of themes) {
    await page.goto(`${base}/components/${file}`);
    await page.evaluate((t) => { document.documentElement.setAttribute('data-theme', t); return document.fonts.ready; }, theme);
    await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
    for (const demo of await page.$$('.ds-demo[data-demo]')) {
      const marker = (await demo.getAttribute('data-demo')).trim().split(/\s+/).join('+');
      const target = await demo.evaluateHandle((d, block) => {
        const row = d.querySelector('.ds-demo__row') || d;
        const first = [...row.children].find((c) => !c.matches('.ds-demo__label, .sr-only, [role=status]')) || row;
        // A wrapper (list, group) is not the component: descend to the block, unless it is a field wrapping a control.
        const el = block && !first.matches(block) && !first.querySelector('input,textarea,select') ? first.querySelector(block) || first : first;
        // Docs grids/flex columns stretch children. Inline-level components (badge, tag, button) are measured at their
        // natural width: probe the display outside the stretching parent, then opt the element out of stretching.
        const probe = document.createElement('div');
        el.before(probe);
        probe.append(el);
        const inline = getComputedStyle(el).display.startsWith('inline');
        probe.replaceWith(el);
        if (inline) Object.assign(el.style, { justifySelf: 'start', alignSelf: 'flex-start' });
        return el;
      }, blocks[name] || `.${name}`);
      const m = await target.evaluate((el) => {
        const box = (e) => {
          const cs = getComputedStyle(e), r = e.getBoundingClientRect(), n = (v) => Math.round((parseFloat(v) || 0) * 100) / 100;
          return { tag: e.tagName.toLowerCase(), width: n(r.width), height: n(r.height),
            padding: [cs.paddingTop, cs.paddingRight, cs.paddingBottom, cs.paddingLeft].map(n), gap: n(cs.columnGap),
            minHeight: n(cs.minHeight), borderWidth: n(cs.borderTopWidth), borderColor: cs.borderTopColor, radius: n(cs.borderTopLeftRadius),
            background: cs.backgroundColor, color: cs.color, fontFamily: cs.fontFamily.split(',')[0].replace(/["']/g, '').trim(),
            fontSize: n(cs.fontSize), fontWeight: n(cs.fontWeight), lineHeight: cs.lineHeight === 'normal' ? null : n(cs.lineHeight),
            boxShadow: cs.boxShadow };
        };
        const sel = 'input:not([type=hidden]),textarea,select,[role=switch],[role=checkbox],button';
        const ctl = el.matches(sel) ? null : el.querySelector(sel);
        const texts = (el.innerText || '').split('\n').map((s) => s.trim()).filter(Boolean).slice(0, 4);
        return { ...box(el), texts, control: ctl ? box(ctl) : null };
      });
      ((result[name] ??= {})[marker] ??= {})[theme] = m;
      const png = `${outDir}/reference/${name}--${marker.replace(/[^\w.+-]/g, '_')}--${theme}.png`;
      try { await target.asElement().screenshot({ path: png, animations: 'disabled', caret: 'hide' }); } catch { /* zero-size */ }
    }
  }
}
writeFileSync(`${outDir}/measured.json`, JSON.stringify(result));
await browser.close();
